#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cfloat>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void min_reduce_kernel_vec4(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int64_t outer, int64_t reduce_size, int64_t inner)
{
    // Each thread processes 4 contiguous elements along the inner (fastest-varying)
    // dimension using vectorized float4 loads/stores. This kernel is only launched
    // when inner is a multiple of 4, guaranteeing that every strided row access
    // (k * inner) is also a multiple of 4 elements, so all float4 accesses across
    // the reduction dimension are 16-byte aligned.
    int64_t o = blockIdx.x;
    int64_t vec_idx = (int64_t)blockIdx.y * blockDim.x + threadIdx.x;
    int64_t i = vec_idx * 4;
    if (o >= outer || i >= inner) return;
    const T* x_base = X + o * reduce_size * inner;
    T* y_base = Y + o * inner;
    float4 acc = *reinterpret_cast<const float4*>(x_base + i);
    #pragma unroll 4
    for (int64_t k = 1; k < reduce_size; ++k) {
        float4 v = *reinterpret_cast<const float4*>(x_base + k * inner + i);
        acc.x = v.x < acc.x ? v.x : acc.x;
        acc.y = v.y < acc.y ? v.y : acc.y;
        acc.z = v.z < acc.z ? v.z : acc.z;
        acc.w = v.w < acc.w ? v.w : acc.w;
    }
    *reinterpret_cast<float4*>(y_base + i) = acc;
}
template <typename T>
__global__ void min_reduce_kernel_scalar(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int64_t outer, int64_t reduce_size, int64_t inner)
{
    // Scalar fallback used whenever inner is not a multiple of 4, since in that
    // case the byte-stride between successive reduction rows (k * inner * sizeof(T))
    // is not guaranteed to be a multiple of 16, making float4 access across the
    // reduction dimension unsafe.
    int64_t o = blockIdx.x;
    int64_t ii = (int64_t)blockIdx.y * blockDim.x + threadIdx.x;
    if (o >= outer || ii >= inner) return;
    const T* x_base = X + o * reduce_size * inner;
    T* y_base = Y + o * inner;
    // Use 8 independent accumulators to break the serial min-dependency chain,
    // exposing more instruction-level parallelism and better overlapping of
    // memory latency across the strided loads along the reduction dimension.
    T acc0 = x_base[ii];
    T acc1 = acc0;
    T acc2 = acc0;
    T acc3 = acc0;
    T acc4 = acc0;
    T acc5 = acc0;
    T acc6 = acc0;
    T acc7 = acc0;
    int64_t k = 1;
    #pragma unroll 8
    for (; k + 7 < reduce_size; k += 8) {
        T v0 = x_base[k * inner + ii];
        T v1 = x_base[(k + 1) * inner + ii];
        T v2 = x_base[(k + 2) * inner + ii];
        T v3 = x_base[(k + 3) * inner + ii];
        T v4 = x_base[(k + 4) * inner + ii];
        T v5 = x_base[(k + 5) * inner + ii];
        T v6 = x_base[(k + 6) * inner + ii];
        T v7 = x_base[(k + 7) * inner + ii];
        acc0 = v0 < acc0 ? v0 : acc0;
        acc1 = v1 < acc1 ? v1 : acc1;
        acc2 = v2 < acc2 ? v2 : acc2;
        acc3 = v3 < acc3 ? v3 : acc3;
        acc4 = v4 < acc4 ? v4 : acc4;
        acc5 = v5 < acc5 ? v5 : acc5;
        acc6 = v6 < acc6 ? v6 : acc6;
        acc7 = v7 < acc7 ? v7 : acc7;
    }
    #pragma unroll 8
    for (; k < reduce_size; ++k) {
        T v = x_base[k * inner + ii];
        acc0 = v < acc0 ? v : acc0;
    }
    T accA = acc0 < acc1 ? acc0 : acc1;
    T accB = acc2 < acc3 ? acc2 : acc3;
    T accC = acc4 < acc5 ? acc4 : acc5;
    T accD = acc6 < acc7 ? acc6 : acc7;
    T accE = accA < accB ? accA : accB;
    T accF = accC < accD ? accC : accD;
    T acc = accE < accF ? accE : accF;
    y_base[ii] = acc;
