    T* y_base = Y + o * inner;
    // Use 8 independent accumulators to break the serial min-dependency chain,
    // exposing more instruction-level parallelism and better overlapping of
    // memory latency across the strided loads along the reduction dimension.
    T acc0 = x_base[ii];
    T acc1 = acc0;
    T acc2 = acc0;
    T acc3 = acc0;
    T acc4 = acc0;
    T acc5 = acc0;
    T acc6 = acc0;
    T acc7 = acc0;
    int64_t k = 1;
    #pragma unroll 8
    for (; k + 7 < reduce_size; k += 8) {
        T v0 = x_base[k * inner + ii];
        T v1 = x_base[(k + 1) * inner + ii];
        T v2 = x_base[(k + 2) * inner + ii];
        T v3 = x_base[(k + 3) * inner + ii];
        T v4 = x_base[(k + 4) * inner + ii];
        T v5 = x_base[(k + 5) * inner + ii];
        T v6 = x_base[(k + 6) * inner + ii];
        T v7 = x_base[(k + 7) * inner + ii];
        acc0 = v0 < acc0 ? v0 : acc0;
        acc1 = v1 < acc1 ? v1 : acc1;
        acc2 = v2 < acc2 ? v2 : acc2;
        acc3 = v3 < acc3 ? v3 : acc3;
        acc4 = v4 < acc4 ? v4 : acc4;
        acc5 = v5 < acc5 ? v5 : acc5;
        acc6 = v6 < acc6 ? v6 : acc6;
        acc7 = v7 < acc7 ? v7 : acc7;
